"    function setLayout(mode) {
      opts.layoutMode = mode;
      nodes.forEach((n, idx) => {
        if (mode === 'clustered') {
          // Explicitly separate into 4 distinct 3D spatial category clusters
          const centers = {
            0: { x: -220, y: -80, z: -100 }, // Flora Cluster (Top-Left)
            1: { x: 220, y: -80, z: 100 },   // Avifauna Cluster (Top-Right)
            2: { x: -220, y: 140, z: 100 },   // Microorganismos Cluster (Bottom-Left)
            3: { x: 220, y: 140, z: -100 }    // Herpetos / MIA Cluster (Bottom-Right)
          };
          const center = centers[n.cat] || { x: 0, y: 0, z: 0 };
          const a = idx * 0.4;
          const r = 40 + (idx % 12) * 5;
          n.ox = center.x + Math.cos(a) * r;
          n.oy = center.y + (idx % 6) * 14 - 35;
          n.oz = center.z + Math.sin(a) * r;
        } else if (mode === 'concentric') {
          const r = 120 + (idx % 5) * 40;
          const a = idx * 0.17;
          n.ox = Math.cos(a) * r;
          n.oy = (idx % 7) * 16 - 48;
          n.oz = Math.sin(a) * r;
        } else if (mode === 'hyperbolic') {
          const phi = Math.acos(1 - 2 * ((idx + 0.5) / nodes.length));
          const theta = Math.PI * (1 + Math.sqrt(5)) * idx;
          const rad = 170 + ((idx * 17) % 110);
          n.ox = rad * Math.sin(phi) * Math.cos(theta);
          n.oy = rad * Math.sin(phi) * Math.sin(theta);
          n.oz = rad * Math.cos(phi);
        }
      });
    }"

