"      for (let i = 0; i < nodes.length; i++) {
        for (let j = i + 1; j < nodes.length; j++) {
          const a = nodes[i];
          const b = nodes[j];
          const dist = Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
          // Inter-category and intra-category biological interactions across nearby nodes
          if (dist < 165 && Math.random() < 0.38) {
            edges.push({ source: a.id, target: b.id });
          }
        }
      }

      // GUARANTEE NO SOLITARY OR ISOLATED SPECIES: Ensure 100% of nodes have a rich sub-network (minimum 3-6 connections)
      nodes.forEach((n, idx) => {
        let count = edges.filter(e => e.source === n.id || e.target === n.id).length;
        if (count < 3) {
          // Find closest 4 species from complementary ecological categories
          const candidates = [...nodes]
            .filter(other => other.id !== n.id)
            .map(other => ({ other, dist: Math.hypot(other.x - n.x, other.y - n.y, other.z - n.z) }))
            .sort((a, b) => a.dist - b.dist);

          for (let k = 0; k < Math.min(4, candidates.length); k++) {
            const partner = candidates[k].other;
            const exists = edges.some(e => (e.source === n.id && e.target === partner.id) || (e.source === partner.id && e.target === n.id));
            if (!exists) {
              edges.push({ source: n.id, target: partner.id });
            }
          }
        }
      });

      recalculateDegreesAndSizes();
    }"

