"    function setLayout(mode) {
      opts.layoutMode = mode;
      nodes.forEach((n, idx) => {
        if (mode === 'clustered') {
          // Fully Decentralized 4-Cluster Organic Multi-Hub (Flora, Avifauna, Micro, Fauna)
          const centers = {
            0: { x: -240, y: -90, z: -120 }, // Flora Hub
            1: { x: 240, y: -90, z: 120 },   // Avifauna Hub
            2: { x: -240, y: 150, z: 120 },   // Microorganismos Hub
            3: { x: 240, y: 150, z: -120 }    // Herpetos / MIA Hub
          };
          const center = centers[n.cat] || { x: 0, y: 0, z: 0 };
          const a = idx * 2.39996 + (n.cat * Math.PI / 2); // Decentralized Golden Angle Offset per category
          const r = 50 + (idx % 15) * 8;
          n.ox = center.x + Math.cos(a) * r;
          n.oy = center.y + Math.sin(a * 1.3) * (r * 0.7);
          n.oz = center.z + Math.sin(a) * r;
        } else if (mode === 'concentric') {
          // Decentralized 3-Ring Multi-Orbit (Distributed across concentric spheres without a single center point)
          const ringIndex = idx % 3;
          const radius = 140 + ringIndex * 85;
          const totalInRing = Math.ceil(nodes.length / 3);
          const posInRing = Math.floor(idx / 3);
          const angle = (posInRing / totalInRing) * Math.PI * 2 + (ringIndex * 0.5);

          n.ox = Math.cos(angle) * radius;
          n.oy = Math.sin(angle * 1.5) * (radius * 0.5);
          n.oz = Math.sin(angle) * radius;
        } else if (mode === 'hyperbolic') {
          // Fully Decentralized Hyperbolic Organic Mesh Sphere (Distributed non-central Golden Spiral)
          const phi = Math.acos(1 - 2 * ((idx + 0.5) / nodes.length));
          const theta = Math.PI * (1 + Math.sqrt(5)) * idx;
          const rad = 210 + ((idx * 29) % 130);
          n.ox = rad * Math.sin(phi) * Math.cos(theta);
          n.oy = rad * Math.sin(phi) * Math.sin(theta);
          n.oz = rad * Math.cos(phi);
        }
      });
    }"

